import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`linkedin-company-rewrite`,heroTitle:`Rewrite your LinkedIn company page in minutes`,heroSubtitle:`Perplexity Computer audits your LinkedIn presence, studies category leaders, and rewrites the page to drive more inbound interest automatically.`,inputUrlCta:`Rewrite my page`,inputUrlPlaceholder:`linkedin.com/company/your-company`,inputUrlPrefill:`Go to {url} and treat it as a LinkedIn company page rewrite project. Pull the current tagline, About section, specialties, featured content, and recent posts. Benchmark strong LinkedIn company pages in the same category to identify better positioning, proof, keyword usage, and calls to action. Then rewrite the company page with a sharper tagline, updated About section, specialty keywords, CTA recommendation, and 5 post drafts designed to increase profile engagement and inbound leads.`,heroOverlaySteps:[`Reading your current LinkedIn company page, specialties, and recent posts`,`Benchmarking how top companies position themselves on LinkedIn`,`Rewriting your tagline, About section, and specialty keyword set`,`Updated profile copy and post ideas ready to publish`],generatingSteps:[`Opening {url} to extract the current LinkedIn company profile and messaging`,`Designing an agent to benchmark leading pages and identify positioning gaps`,`Configuring rewritten company copy, keyword recommendations, and CTA updates`,`Preparing a publishing pack with post drafts and implementation notes`],featureSectionTitle:`From static profile to LinkedIn growth asset`,featureCardTitles:[`Connects to your social workflow`,`Copy you can publish today`],featureCardDescriptions:[`Computer blends profile research, market positioning, copywriting, and social content planning with the right model for each step.`,`LinkedIn, Docs, Sheets, Notion, and Drive fit into one workflow so brand, growth, and recruiting teams can collaborate.`,`A rewritten tagline, About section, specialty list, CTA recommendation, and starter post drafts come back ready for rollout.`],capabilitySectionTitle:`Your LinkedIn brand strategist, on autopilot`,capabilitySectionSubtitle:`Paste your company page URL and come back to a sharper LinkedIn presence.`,capabilityCards:[{title:`Profile Audit`,description:`Computer can assess your current company page for clarity, differentiation, keyword coverage, and proof signals that influence inbound interest.`},{title:`Category Benchmarking`,description:`Computer can analyze high-performing peer pages to identify the positioning moves, topic angles, and CTAs that stand out in your market.`},{title:`Rewrite Package`,description:`Computer can rewrite the core profile copy and recommend specialty keywords, CTA language, and post ideas aligned to your brand.`},{title:`Connect Your Tools`,description:`Computer can move copy and review notes into the docs and planning tools your team already uses.`},{title:`Remember Brand Voice`,description:`Computer can learn your positioning, audience, and preferred tone so future updates stay consistent.`},{title:`Spot Drift Early`,description:`Computer can re-audit the page after updates and flag when the profile starts drifting away from your strongest positioning.`}]});export{t as default};
